<script setup lang="ts">
import { ref, watch } from 'vue'
import { qtrc, useLanguage } from '../../../i18n'
import { ICON_CODES } from '../../../actions/uiactiondata'
import type { NotationStyleLike } from './controls.vue'
const props=defineProps<{style:NotationStyleLike;goToTextStylePage?:(id:string|number)=>void}>()
useLanguage()
const tr=(s:string)=>qtrc('notation',s)
const fields=[{id:'fretY',label:'Position above staff:',step:0.05},{id:'fretMinDistance',label:'Min. space to notation:',step:0.05},{id:'fretMag',label:'Scale:',step:1,percent:true},{id:'fretNutThickness',label:'Nut line thickness:',step:0.01},{id:'fretDotSpatiumSize',label:'Dot size:',step:0.01},{id:'barreLineWidth',label:'Line thickness:',step:1,percent:true},{id:'fretStringSpacing',label:'String spacing:',step:0.01},{id:'fretFretSpacing',label:'Fret spacing:',step:0.01}]
function shown(f:typeof fields[number]){const v=Number(props.style.value(f.id) ?? 0);return String(f.percent?Math.round(v*100):v)}
const values=ref<Record<string,string>>(Object.fromEntries(fields.map(f=>[f.id,shown(f)])))
watch(()=>fields.map(f=>props.style.value(f.id)),()=>fields.forEach(f=>{values.value[f.id]=shown(f)}))
function commit(f:typeof fields[number]){const n=parseFloat(values.value[f.id].replace(',','.'));if(Number.isFinite(n)){const v=Math.max(0,Math.min(f.percent?999:99,n));props.style.setValue(f.id,f.percent?Math.round(v)/100:Number(v.toFixed(2)))}values.value[f.id]=shown(f)}
function step(f:typeof fields[number],d:number){values.value[f.id]=String((parseFloat(values.value[f.id].replace(',','.'))||0)+d*f.step);commit(f)}
const selectors=[{id:'fretOrientation',label:'Orientation:',icons:[ICON_CODES.FRETBOARD_VERTICAL,ICON_CODES.FRETBOARD_HORIZONTAL],texts:['Vertical','Horizontal'],values:[0,1]},{id:'barreAppearanceSlur',label:'Appearance:',icons:[ICON_CODES.FRETBOARD_BARRE_LINE,ICON_CODES.FRETBOARD_BARRE_SLUR],texts:['Line','Slur'],values:[false,true]},{id:'fretStyleExtended',label:'Fretboard style:',icons:[ICON_CODES.FRETBOARD_VERTICAL,ICON_CODES.FRETBOARD_EXTENDED],texts:['Trimmed','Extended'],values:[false,true]}]
</script>
<template>
<fieldset class="sd-groupbox"><legend>{{ tr('Fretboard diagrams') }}</legend><div class="sd-column" style="gap:12px">
  <template v-for="f in fields" :key="f.id">
    <div v-if="f.id==='fretStringSpacing'" v-for="s in [selectors[2]]" :key="s.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px">{{ tr(s.label) }}</div><div class="sd-row-control" style="width:204px"><div class="sd-flat-radio-group" role="radiogroup" :aria-label="tr(s.label)" style="gap:4px"><button v-for="(icon,index) in s.icons" :key="index" type="button" role="radio" class="sd-flat-radio stacked" style="height:70px" :aria-checked="style.value(s.id)===s.values[index]" @click="style.setValue(s.id,s.values[index])"><span class="sd-icon" aria-hidden="true" style="font-size:28px">{{ String.fromCodePoint(icon) }}</span>{{ tr(s.texts[index]) }}</button></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(s.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div>
    <div v-if="f.id==='fretDotSpatiumSize'" class="sd-column" style="gap:12px"><fieldset class="sd-groupbox"><legend>{{ tr('Fret number') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:12px"><span class="sd-label">{{ tr('Position:') }}</span><label v-for="index in [0,1]" :key="index" class="sd-radio"><input type="radio" name="fret-position" :checked="style.value('fretNumPos')===index" @change="style.setValue('fretNumPos',index)"><span>{{ tr(style.value('fretOrientation')===0 ? (index===0?'Left':'Right') : (index===0?'Bottom':'Top')) }}</span></label></div><fieldset class="sd-groupbox"><legend>{{ tr('Format:') }}</legend><div class="sd-column" style="gap:12px"><label class="sd-radio"><input type="radio" name="fret-suffix" :checked="!style.value('fretUseCustomSuffix')" @change="style.setValue('fretUseCustomSuffix',false)"><span>{{ tr('Number only') }}</span></label><div class="sd-row" style="gap:8px"><label class="sd-radio"><input type="radio" name="fret-suffix" :checked="style.value('fretUseCustomSuffix')===true" @change="style.setValue('fretUseCustomSuffix',true)"><span>{{ tr('Custom suffix:') }}</span></label><input class="sd-text" style="width:60px" :disabled="!style.value('fretUseCustomSuffix')" :aria-label="tr('Custom suffix:')" :value="style.value('fretCustomSuffix')" @input="style.setValue('fretCustomSuffix',($event.target as HTMLInputElement).value)"><span v-if="style.value('fretUseCustomSuffix')" class="sd-label">{{ tr('Preview:') }} 3{{ style.value('fretCustomSuffix') }}</span></div></div></fieldset><div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('fretboard-diagram-fret-number')">{{ tr('Edit fret number text style') }}</button></div></div></fieldset></div>
    <fieldset v-if="f.id==='barreLineWidth'" class="sd-groupbox"><legend>{{ tr('Barré') }}</legend><div class="sd-column" style="gap:12px"><div v-for="s in [selectors[1]]" :key="s.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px">{{ tr(s.label) }}</div><div class="sd-row-control" style="width:204px"><div class="sd-flat-radio-group" role="radiogroup" :aria-label="tr(s.label)" style="gap:4px"><button v-for="(icon,index) in s.icons" :key="index" type="button" role="radio" class="sd-flat-radio stacked" style="height:70px" :aria-checked="style.value(s.id)===s.values[index]" @click="style.setValue(s.id,s.values[index])"><span class="sd-icon" aria-hidden="true" style="font-size:28px">{{ String.fromCodePoint(icon) }}</span>{{ tr(s.texts[index]) }}</button></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="tr('Reset')" @click="style.resetValue?.(s.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px">{{ tr(f.label) }}</div><div class="sd-row-control" style="width:204px"><div class="sd-spinbox" style="width:80px"><input v-model="values[f.id]" type="text" inputmode="decimal" :aria-label="tr(f.label)" @blur="commit(f)" @keydown.enter.prevent="commit(f)" @keydown.up.prevent="step(f,1)" @keydown.down.prevent="step(f,-1)"><span class="sd-unit">%</span><span class="sd-steppers"><button type="button" tabindex="-1" aria-label="+" @mousedown.prevent @click="step(f,1)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_UP) }}</button><button type="button" tabindex="-1" aria-label="-" @mousedown.prevent @click="step(f,-1)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</button></span></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="tr('Reset')" @click="style.resetValue?.(f.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></fieldset>
    <div v-else class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px">{{ tr(f.label) }}</div><div class="sd-row-control" style="width:204px"><div class="sd-spinbox" style="width:80px"><input v-model="values[f.id]" type="text" inputmode="decimal" :aria-label="tr(f.label)" @blur="commit(f)" @keydown.enter.prevent="commit(f)" @keydown.up.prevent="step(f,1)" @keydown.down.prevent="step(f,-1)"><span class="sd-unit">{{ f.percent?'%':qtrc('global','sp') }}</span><span class="sd-steppers"><button type="button" tabindex="-1" aria-label="+" @mousedown.prevent @click="step(f,1)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_UP) }}</button><button type="button" tabindex="-1" aria-label="-" @mousedown.prevent @click="step(f,-1)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</button></span></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(f.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div>
    <div v-if="f.id==='fretMag'" v-for="s in [selectors[0]]" :key="s.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px">{{ tr(s.label) }}</div><div class="sd-row-control" style="width:204px"><div class="sd-flat-radio-group" role="radiogroup" :aria-label="tr(s.label)" style="gap:4px"><button v-for="(icon,index) in s.icons" :key="index" type="button" role="radio" class="sd-flat-radio stacked" style="height:70px" :aria-checked="style.value(s.id)===s.values[index]" @click="style.setValue(s.id,s.values[index])"><span class="sd-icon" aria-hidden="true" style="font-size:28px">{{ String.fromCodePoint(icon) }}</span>{{ tr(s.texts[index]) }}</button></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(s.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div>
    <div v-if="f.id==='barreLineWidth'" class="sd-column" style="gap:12px"><label class="sd-checkbox"><input type="checkbox" :checked="style.value('fretShowFingerings')===true" @change="style.setValue('fretShowFingerings',!style.value('fretShowFingerings'))"><span>{{ tr('Show fingerings') }}</span></label><div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('fretboard-diagram-fingering')">{{ tr('Edit fingering text style') }}</button></div></div>
  </template>
</div></fieldset>
</template>
